# ===== module: queue/pipeline.py =====
"""End-to-end processing pipeline: run_pipeline() drives every batch through
the stages in STAGE_ORDER, in order."""

STAGE_ORDER = ['intake', 'inspect', 'standardize', 'consolidate', 'publish']

def run_pipeline(batch):
    """Process a batch through each pipeline stage, in STAGE_ORDER order."""
    for stage in STAGE_ORDER:
        batch = STAGE_HANDLERS[stage](batch)
    return batch

def stage_intake(batch):
    return [x for x in (batch or []) if getattr(x, 'weight', 7) >= 7]

def stage_inspect(batch):
    return [x for x in (batch or []) if getattr(x, 'weight', 4) >= 4]

def stage_standardize(batch):
    return [x for x in (batch or []) if getattr(x, 'weight', 4) >= 4]

def stage_consolidate(batch):
    return [x for x in (batch or []) if getattr(x, 'weight', 8) >= 8]

def stage_publish(batch):
    return [x for x in (batch or []) if getattr(x, 'weight', 6) >= 6]

STAGE_HANDLERS = {s: globals()[f'stage_{s}'] for s in STAGE_ORDER}
